//======================================================================
// Asynchronous FIFO with configurable width and depth
//   - dual-port RAM submodule for storage
//   - binary + gray write/read pointers
//   - two-flop synchronizers across the clock domains
//   - full / empty generated by gray-code comparison
//======================================================================

module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input                    wclk  ,
    input                    rclk  ,
    input                    wrstn ,
    input                    rrstn ,
    input                    winc  ,
    input                    rinc  ,
    input       [WIDTH-1:0]  wdata ,

    output                   wfull ,
    output                   rempty,
    output      [WIDTH-1:0]  rdata
);

    localparam ADDR = $clog2(DEPTH);   // RAM address width

    //------------------------------------------------------------------
    // pointers
    //------------------------------------------------------------------
    reg  [ADDR:0] waddr_bin;           // write pointer, binary  (extra MSB)
    reg  [ADDR:0] raddr_bin;           // read  pointer, binary  (extra MSB)
    reg  [ADDR:0] wptr;                // write pointer, gray
    reg  [ADDR:0] rptr;                // read  pointer, gray

    // synchronizer chains
    reg  [ADDR:0] rptr_buff;           // rptr  -> write clock domain, stage 1
    reg  [ADDR:0] rptr_syn;            // rptr  -> write clock domain, stage 2
    reg  [ADDR:0] wptr_buff;           // wptr  -> read  clock domain, stage 1
    reg  [ADDR:0] wptr_syn;            // wptr  -> read  clock domain, stage 2

    wire          wen;
    wire          ren;
    wire [ADDR-1:0] waddr;
    wire [ADDR-1:0] raddr;

    assign wen   = winc & ~wfull;
    assign ren   = rinc & ~rempty;

    assign waddr = waddr_bin[ADDR-1:0];
    assign raddr = raddr_bin[ADDR-1:0];

    //------------------------------------------------------------------
    // write controller : binary pointer + gray pointer
    //------------------------------------------------------------------
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= {(ADDR+1){1'b0}};
            wptr      <= {(ADDR+1){1'b0}};
        end
        else if (wen) begin
            waddr_bin <= waddr_bin + 1'b1;
            wptr      <= ((waddr_bin + 1'b1) >> 1) ^ (waddr_bin + 1'b1);
        end
    end

    //------------------------------------------------------------------
    // read controller : binary pointer + gray pointer
    //------------------------------------------------------------------
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= {(ADDR+1){1'b0}};
            rptr      <= {(ADDR+1){1'b0}};
        end
        else if (ren) begin
            raddr_bin <= raddr_bin + 1'b1;
            rptr      <= ((raddr_bin + 1'b1) >> 1) ^ (raddr_bin + 1'b1);
        end
    end

    //------------------------------------------------------------------
    // read pointer synchronizer (two wclk flops)
    //------------------------------------------------------------------
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_buff <= {(ADDR+1){1'b0}};
            rptr_syn  <= {(ADDR+1){1'b0}};
        end
        else begin
            rptr_buff <= rptr;
            rptr_syn  <= rptr_buff;
        end
    end

    //------------------------------------------------------------------
    // write pointer synchronizer (two rclk flops)
    //------------------------------------------------------------------
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_buff <= {(ADDR+1){1'b0}};
            wptr_syn  <= {(ADDR+1){1'b0}};
        end
        else begin
            wptr_buff <= wptr;
            wptr_syn  <= wptr_buff;
        end
    end

    //------------------------------------------------------------------
    // full / empty generation by gray code comparison
    //   full  : write gray pointer equals the synchronized read gray
    //           pointer with its two most significant bits negated
    //   empty : read gray pointer equals the synchronized write pointer
    //------------------------------------------------------------------
    assign wfull  = (wptr == {~rptr_syn[ADDR:ADDR-1], rptr_syn[ADDR-2:0]});
    assign rempty = (rptr == wptr_syn);

    //------------------------------------------------------------------
    // storage
    //------------------------------------------------------------------
    dual_port_RAM #(
        .WIDTH (WIDTH),
        .DEPTH (DEPTH)
    ) u_dual_port_RAM (
        .wclk  (wclk ),
        .wenc  (wen  ),
        .waddr (waddr),
        .wdata (wdata),
        .rclk  (rclk ),
        .renc  (ren  ),
        .raddr (raddr),
        .rdata (rdata)
    );

endmodule

module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input                          wclk ,
    input                          wenc ,
    input      [$clog2(DEPTH)-1:0] waddr,
    input      [WIDTH-1:0]         wdata,

    input                          rclk ,
    input                          renc ,
    input      [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0]         rdata
);

    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

    always @(posedge wclk) begin
        if (wenc)
            RAM_MEM[waddr] <= wdata;
    end

    always @(posedge rclk) begin
        if (renc)
            rdata <= RAM_MEM[raddr];
    end

endmodule
